SELECT market, symbol, bar_time, open_price, high_price, low_price,
       close_price, volume, turnover, created_at, updated_at
FROM tb_minute_bar
WHERE market = #{market}
  AND symbol = #{symbol}
  AND bar_time BETWEEN #{start} AND #{end}
ORDER BY bar_time ASC

SELECT COUNT(*)
FROM tb_minute_bar
WHERE market = #{market}
  AND symbol = #{symbol}
  AND bar_time BETWEEN #{start} AND #{end}
